def transform(g):
    H,W=len(g),len(g[0])
    # find separator value: a value forming full uniform rows
    seps=set()
    for i in range(H):
        vals=set(g[i])
        if len(vals)==1:
            v=vals.pop()
            if any(all(g[r][j]==v for r in range(H)) for j in range(W)):
                seps.add(v)
    s=seps.pop()
    sepR=[i for i in range(H) if all(x==s for x in g[i])]
    sepC=[j for j in range(W) if all(g[i][j]==s for i in range(H))]
    def spans(sep,n):
        sp=[];start=0
        for x in sep: sp.append((start,x-1));start=x+1
        sp.append((start,n-1))
        return [x for x in sp if x[1]>=x[0]]
    rs=spans(sepR,H);cs=spans(sepC,W)
    r0,r1=rs[0];c0,c1=cs[0]
    tile=[row[c0:c1+1] for row in g[r0:r1+1]]
    out=[row[:] for row in g]
    for (a,b) in rs:
        for (c,d) in cs:
            for i in range(a,b+1):
                for j in range(c,d+1):
                    out[i][j]=tile[i-a][j-c]
    return out
